using System.Text.Json.Nodes;
using System.Security.Cryptography;
using Microsoft.Data.SqlClient;
namespace MyProjectManagement;
public static class ChangeRequestApi {
 static async Task<JsonObject> Body(HttpContext ctx)=>(await JsonNode.ParseAsync(ctx.Request.Body))?.AsObject()??throw new ApiError(400,"JSON object required");
 static async Task<JsonObject> Load(SqlConnection c,SqlTransaction? tx,Guid workspace,string id){await using var q=new SqlCommand("SELECT Payload,Version FROM dbo.ChangeRequests "+(tx is null?"":"WITH(UPDLOCK,HOLDLOCK) ")+"WHERE WorkspaceId=@w AND Id=TRY_CONVERT(uniqueidentifier,@id)",c,tx);q.Parameters.AddWithValue("@w",workspace);q.Parameters.AddWithValue("@id",id);await using var reader=await q.ExecuteReaderAsync();J.Require(await reader.ReadAsync(),"Change request not found",404);var row=JsonNode.Parse(reader.GetString(0))!.AsObject();row["version"]=reader.GetInt32(1);return row;}
 static async Task Persist(SqlConnection c,SqlTransaction tx,Guid workspace,JsonObject row,bool create=false){if(J.S(row,"externalNumberKey")!=""){await using var duplicate=new SqlCommand("SELECT COUNT(*) FROM dbo.ChangeRequests cr LEFT JOIN dbo.WorkspaceRecords pr ON pr.WorkspaceId=cr.WorkspaceId AND pr.Kind='project' AND pr.RecordId COLLATE DATABASE_DEFAULT=cr.ProjectId COLLATE DATABASE_DEFAULT WHERE cr.WorkspaceId=@w AND cr.Id<>@id AND (JSON_VALUE(cr.Payload,'$.externalNumberKey') COLLATE Latin1_General_100_BIN2=@n OR UPPER(LTRIM(RTRIM(cr.Number))) COLLATE Latin1_General_100_BIN2=@n) AND (cr.ProjectId=@p OR (@customer<>N'' AND COALESCE(NULLIF(JSON_VALUE(cr.Payload,'$.customerId'),N''),JSON_VALUE(pr.Payload,'$.customerId')) COLLATE DATABASE_DEFAULT=@customer))",c,tx);duplicate.Parameters.AddWithValue("@w",workspace);duplicate.Parameters.AddWithValue("@id",Guid.Parse(J.S(row,"id")));duplicate.Parameters.AddWithValue("@n",J.S(row,"externalNumberKey"));duplicate.Parameters.AddWithValue("@p",J.S(row,"projectId"));duplicate.Parameters.AddWithValue("@customer",J.S(row,"customerId"));J.Require(Convert.ToInt32(await duplicate.ExecuteScalarAsync())==0,"This CR number already exists for the selected customer or project. Open that request and create a new revision instead",409);}int version=(int)J.N(row,"version",0);row["version"]=version+1;var revision=ChangeRequests.Latest(row);if(create)await Db.Exec(c,tx,"INSERT dbo.ChangeRequests(WorkspaceId,Id,ProjectId,InitiatorId,Number,Version,Payload,UpdatedAt) VALUES(@w,@id,@p,@i,@n,@v,@json,SYSUTCDATETIME())",("@w",workspace),("@id",Guid.Parse(J.S(row,"id"))),("@p",J.S(row,"projectId")),("@i",J.S(row,"initiatorId")),("@n",J.S(row,"number")),("@v",version+1),("@json",row.ToJsonString()));else{int count=await Db.Exec(c,tx,"UPDATE dbo.ChangeRequests SET Version=@next,Payload=@json,UpdatedAt=SYSUTCDATETIME() WHERE WorkspaceId=@w AND Id=@id AND Version=@old",("@w",workspace),("@id",Guid.Parse(J.S(row,"id"))),("@old",version),("@next",version+1),("@json",row.ToJsonString()));J.Require(count==1,"CONFLICT: change request was updated. Reload and retry",409);}}
 static string WordName(JsonObject body){var name=J.S(body,"name").Replace('\\','/').Split('/').Last();J.Require(name.Length is >0 and <=100&&name.EndsWith(".docx",StringComparison.OrdinalIgnoreCase)&&!name.Any(char.IsControl),"Choose a .docx file with a name up to 100 characters",400);return name;}
 static byte[] WordBytes(JsonObject body){WordName(body);byte[] bytes;try{bytes=Convert.FromBase64String(J.S(body,"base64"));}catch(FormatException){throw new ApiError(400,"Invalid document data");}J.Require(bytes.Length is >0 and <=5242880,"Upload Word .docx up to 5 MB",400);return bytes;}
 static async Task<byte[]> StoredBytes(SqlConnection c,SqlTransaction tx,Guid workspace,string request,string document){await using var q=new SqlCommand("SELECT Content FROM dbo.ChangeRequestDocuments WHERE WorkspaceId=@w AND RequestId=TRY_CONVERT(uniqueidentifier,@r) AND Id=TRY_CONVERT(uniqueidentifier,@d)",c,tx);q.Parameters.AddWithValue("@w",workspace);q.Parameters.AddWithValue("@r",request);q.Parameters.AddWithValue("@d",document);var result=await q.ExecuteScalarAsync();J.Require(result is byte[],"Upload the current Word document before saving mapped fields",400);return (byte[])result!;}
 static async Task StoreWord(SqlConnection c,SqlTransaction tx,Guid workspace,JsonObject row,Policy policy,byte[] bytes,string name,string origin){var revision=ChangeRequests.Latest(row);J.Require(revision["documents"]!.AsArray().Count<20,"Maximum 20 document versions per revision; start a new revision after review",400);var id=Guid.NewGuid();string hash=Convert.ToHexString(SHA256.HashData(bytes));var metadata=new JsonObject{["id"]=id.ToString(),["name"]=name,["size"]=bytes.Length,["sha256"]=hash,["paragraphCount"]=ChangeRequests.Preview(bytes,name).Count,["uploadedBy"]=policy.Actor,["uploadedAt"]=DateTimeOffset.UtcNow.ToString("O"),["origin"]=origin};ChangeRequests.Upload(new Snapshot(),policy,row,metadata);await Db.Exec(c,tx,"INSERT dbo.ChangeRequestDocuments(WorkspaceId,Id,RequestId,RevisionNo,FileName,ContentType,Content,Sha256) VALUES(@w,@id,@r,@n,@name,@type,@bytes,@hash)",("@w",workspace),("@id",id),("@r",Guid.Parse(J.S(row,"id"))),("@n",(int)J.N(revision,"number")),("@name",name),("@type","application/vnd.openxmlformats-officedocument.wordprocessingml.document"),("@bytes",bytes),("@hash",hash));}
 public static void Map(WebApplication app,Func<HttpContext,Db,Task<AppUser>> current){
 app.Use(async(ctx,next)=>{if(ctx.Request.Path.StartsWithSegments("/api/change-requests")){ctx.Response.Headers.CacheControl="no-store";ctx.Response.Headers["X-Content-Type-Options"]="nosniff";}await next();});
 app.MapPost("/api/change-requests/document-preview",async(HttpContext ctx,Db db)=>{var user=await current(ctx,db);var body=await Body(ctx);await using var c=await db.Open();var state=await db.Load(user.Workspace,c);var policy=new Policy(state,user);J.Require(policy.Flag("createChangeRequests")&&policy.ProjectScope(J.S(body,"projectId")),"Word import requires CR creation permission and project access");var bytes=WordBytes(body);return Results.Json(ChangeRequestWord.Read(bytes));}).RequireAuthorization();
 app.MapPost("/api/change-requests/from-word",async(HttpContext ctx,Db db)=>{var user=await current(ctx,db);var body=await Body(ctx);J.Require(J.B(body,"confirmProject"),"Confirm the selected project/customer matches the Word document",400);await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var state=await db.Load(user.Workspace,c,tx);var policy=new Policy(state,user);J.Require(policy.Flag("createChangeRequests")&&policy.ProjectScope(J.S(body,"projectId")),"Word import requires CR creation permission and project access");var bytes=WordBytes(body);var mapping=ChangeRequestWord.Read(bytes);var row=ChangeRequests.Create(state,policy,StructuredChangeRequest.DraftBody(body,mapping));await Persist(c,tx,user.Workspace,row,true);await StoreWord(c,tx,user.Workspace,row,policy,bytes,WordName(body),"Original upload");var revision=ChangeRequests.Latest(row);var edited=ChangeRequestWord.Rewrite(bytes,revision["header"]!.AsObject(),revision["points"]!.AsArray());await StoreWord(c,tx,user.Workspace,row,policy,edited,"Mapped-"+WordName(body),"Mapped Word document");await Persist(c,tx,user.Workspace,row);await tx.CommitAsync();return Results.Json(row);}).RequireAuthorization();
 app.MapPost("/api/change-requests/{id}/form",async(string id,HttpContext ctx,Db db)=>{var user=await current(ctx,db);var body=await Body(ctx);await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var state=await db.Load(user.Workspace,c,tx);var row=await Load(c,tx,user.Workspace,id);var policy=new Policy(state,user);J.Require(ChangeRequests.Read(policy,row)&&J.S(row,"initiatorId")==policy.Actor&&policy.Flag("createChangeRequests")&&J.S(ChangeRequests.Latest(row),"state")=="Draft","Only the initiator may edit the current draft");J.Require(J.N(body,"expectedVersion",-1)==J.N(row,"version"),"CONFLICT: reload this request before saving",409);var revision=ChangeRequests.Latest(row);bool uploaded=J.S(body,"base64")!="";string name=uploaded?WordName(body):"CR-R"+J.N(revision,"number")+".docx";byte[] bytes;if(uploaded)bytes=WordBytes(body);else bytes=await StoredBytes(c,tx,user.Workspace,id,J.S(revision,"documentId")==""?J.S(revision,"sourceDocumentId"):J.S(revision,"documentId"));var mapping=ChangeRequestWord.Read(bytes,revision["points"] as JsonArray);ChangeRequests.Act(state,policy,row,"save",StructuredChangeRequest.DraftBody(body,mapping));if(uploaded)await StoreWord(c,tx,user.Workspace,row,policy,bytes,name,"Original revised upload");var output=ChangeRequestWord.Rewrite(bytes,revision["header"]!.AsObject(),revision["points"]!.AsArray());await StoreWord(c,tx,user.Workspace,row,policy,output,"Mapped-"+name,"Mapped Word document");await Persist(c,tx,user.Workspace,row);await tx.CommitAsync();return Results.Json(row);}).RequireAuthorization();
 app.MapGet("/api/change-requests",async(HttpContext ctx,Db db)=>{var u=await current(ctx,db);await using var c=await db.Open();var s=await db.Load(u.Workspace,c);var p=new Policy(s,u);J.Require(p.Active,"Inactive account");var rows=new JsonArray();await using var q=new SqlCommand("SELECT Payload,Version FROM dbo.ChangeRequests WHERE WorkspaceId=@w ORDER BY UpdatedAt DESC",c);q.Parameters.AddWithValue("@w",u.Workspace);await using var r=await q.ExecuteReaderAsync();while(await r.ReadAsync()){var row=JsonNode.Parse(r.GetString(0))!.AsObject();if(!ChangeRequests.Read(p,row))continue;var rev=ChangeRequests.Latest(row);rows.Add(new JsonObject{["id"]=J.S(row,"id"),["number"]=J.S(row,"number"),["externalNumber"]=J.S(rev["header"],"externalNumber"),["customerId"]=J.S(row,"customerId"),["projectId"]=J.S(row,"projectId"),["projectName"]=J.S(p.Project(J.S(row,"projectId")),"name")==""?J.S(row,"projectName"):J.S(p.Project(J.S(row,"projectId")),"name"),["initiatorId"]=J.S(row,"initiatorId"),["revision"]=(int)J.N(rev,"number"),["title"]=J.S(rev,"title"),["state"]=J.S(rev,"state"),["pmId"]=J.S(rev,"pmId"),["ctoId"]=J.S(rev,"ctoId"),["version"]=r.GetInt32(1),["updatedAt"]=J.S(row,"updatedAt")});if(rows.Count>=200)break;}return Results.Json(rows);}).RequireAuthorization();
 app.MapGet("/api/change-requests/{id}",async(string id,HttpContext ctx,Db db)=>{var u=await current(ctx,db);await using var c=await db.Open();var s=await db.Load(u.Workspace,c);var row=await Load(c,null,u.Workspace,id);J.Require(ChangeRequests.Read(new Policy(s,u),row),"Change request access denied");return Results.Json(row);}).RequireAuthorization();
 app.MapPost("/api/change-requests",async(HttpContext ctx,Db db)=>{var u=await current(ctx,db);var body=await Body(ctx);await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var s=await db.Load(u.Workspace,c,tx);var row=ChangeRequests.Create(s,new Policy(s,u),body);await Persist(c,tx,u.Workspace,row,true);await tx.CommitAsync();return Results.Json(row);}).RequireAuthorization();
 app.MapPost("/api/change-requests/{id}/action",async(string id,HttpContext ctx,Db db)=>{var u=await current(ctx,db);var body=await Body(ctx);await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var s=await db.Load(u.Workspace,c,tx);var row=await Load(c,tx,u.Workspace,id);J.Require(J.N(body,"expectedVersion",-1)==J.N(row,"version"),"CONFLICT: change request changed. Reload before deciding",409);J.Require(J.S(body,"action")!="save"||ChangeRequests.Latest(row)["header"] is not JsonObject,"Save the mapped form to keep the Word document synchronized",400);ChangeRequests.Act(s,new Policy(s,u),row,J.S(body,"action"),body);await Persist(c,tx,u.Workspace,row);await tx.CommitAsync();return Results.Json(row);}).RequireAuthorization();
 app.MapPost("/api/change-requests/{id}/documents",async(string id,HttpContext ctx,Db db)=>{var u=await current(ctx,db);var body=await Body(ctx);byte[] bytes;try{bytes=Convert.FromBase64String(J.S(body,"base64"));}catch(FormatException){throw new ApiError(400,"Invalid document data");}J.Require(bytes.Length is >0 and <=5*1024*1024,"Word documents must be between 1 byte and 5 MB",400);var name=J.S(body,"name").Replace('\\','/').Split('/').Last();J.Require(name.Length is >0 and <=120&&!name.Any(char.IsControl),"Use a file name up to 120 characters",400);bool docx=name.EndsWith(".docx",StringComparison.OrdinalIgnoreCase),doc=name.EndsWith(".doc",StringComparison.OrdinalIgnoreCase);J.Require(docx||doc,"Upload a Word .docx or .doc file",400);int paragraphCount=docx?ChangeRequests.Preview(bytes,name).Count:0;if(!docx) J.Require(bytes.Length>=8&&bytes.Take(8).SequenceEqual(new byte[]{0xD0,0xCF,0x11,0xE0,0xA1,0xB1,0x1A,0xE1}),"Invalid legacy Word document",400);
 await using var c=await db.Open();await using var tx=(SqlTransaction)await c.BeginTransactionAsync();var s=await db.Load(u.Workspace,c,tx);var row=await Load(c,tx,u.Workspace,id);J.Require(J.N(body,"expectedVersion",-1)==J.N(row,"version"),"CONFLICT: reload before uploading",409);J.Require(ChangeRequests.Latest(row)["header"] is not JsonObject,"Use the mapped form upload to synchronize Word fields",400);var document=Guid.NewGuid();var type=docx?"application/vnd.openxmlformats-officedocument.wordprocessingml.document":"application/msword";var hash=Convert.ToHexString(SHA256.HashData(bytes));var metadata=new JsonObject{["id"]=document.ToString(),["name"]=name,["size"]=bytes.Length,["paragraphCount"]=paragraphCount,["sha256"]=hash,["uploadedBy"]=new Policy(s,u).Actor,["uploadedAt"]=DateTimeOffset.UtcNow.ToString("O")};J.Require(ChangeRequests.Latest(row)["documents"]!.AsArray().Count<20,"Maximum 20 uploads per revision",400);ChangeRequests.Upload(s,new Policy(s,u),row,metadata);await Db.Exec(c,tx,"INSERT dbo.ChangeRequestDocuments(WorkspaceId,Id,RequestId,RevisionNo,FileName,ContentType,Content,Sha256) VALUES(@w,@id,@r,@n,@name,@type,@bytes,@hash)",("@w",u.Workspace),("@id",document),("@r",Guid.Parse(id)),("@n",(int)J.N(ChangeRequests.Latest(row),"number")),("@name",name),("@type",type),("@bytes",bytes),("@hash",hash));await Persist(c,tx,u.Workspace,row);await tx.CommitAsync();return Results.Json(row);}).RequireAuthorization();
 app.MapGet("/api/change-requests/{id}/documents/{document}",async(string id,string document,HttpContext ctx,Db db)=>{var u=await current(ctx,db);await using var c=await db.Open();var s=await db.Load(u.Workspace,c);var row=await Load(c,null,u.Workspace,id);J.Require(ChangeRequests.Read(new Policy(s,u),row),"Document access denied");await using var q=new SqlCommand("SELECT FileName,ContentType,Content FROM dbo.ChangeRequestDocuments WHERE WorkspaceId=@w AND RequestId=TRY_CONVERT(uniqueidentifier,@r) AND Id=TRY_CONVERT(uniqueidentifier,@d)",c);q.Parameters.AddWithValue("@w",u.Workspace);q.Parameters.AddWithValue("@r",id);q.Parameters.AddWithValue("@d",document);await using var reader=await q.ExecuteReaderAsync();J.Require(await reader.ReadAsync(),"Document not found",404);string name=reader.GetString(0),type=reader.GetString(1);byte[] bytes=(byte[])reader.GetValue(2);ctx.Response.Headers.CacheControl="no-store";ctx.Response.Headers["X-Content-Type-Options"]="nosniff";if(ctx.Request.Query["preview"]=="true")return (IResult)Results.Json(new{fileName=name,paragraphs=ChangeRequests.Preview(bytes,name),html=name.EndsWith(".docx",StringComparison.OrdinalIgnoreCase)?ChangeRequestWord.PreviewHtml(bytes):"",note=name.EndsWith(".docx",StringComparison.OrdinalIgnoreCase)?"Read-only text preview. Formatting, images and tracked changes are not reproduced. D numbers identify preview paragraphs for review comments.":"Legacy .doc: download and open in Word. Upload .docx for an in-app text preview."});return Results.File(bytes,type,name);}).RequireAuthorization();
 }
